script:
if (-not $SERVICE_NAME -or -not $PAYLOAD_PATH) { throw 'SERVICE_NAME and PAYLOAD_PATH are required' }
$dir = Split-Path $PAYLOAD_PATH -Parent
New-Item -ItemType Directory -Force -Path $dir | Out-Null
if ($PAYLOAD_BODY) { Set-Content -Path $PAYLOAD_PATH -Value $PAYLOAD_BODY -Encoding ascii }
$startup = if ($STARTUP) { $STARTUP } else { 'Automatic' }
$existing = Get-Service -Name $SERVICE_NAME -ErrorAction Ignore
if ($existing) {
    Stop-Service -Name $SERVICE_NAME -Force -ErrorAction Ignore
    sc.exe delete $SERVICE_NAME | Out-Null
    Start-Sleep -Seconds 2
}
# powershell.exe cannot BE a service binary (the SCM kills console apps after
# 30s with error 1053) -- compile a tiny SCM wrapper around the payload with
# the .NET Framework C# compiler that ships on every Windows 10/Server box.
$cls = 'Wrap' + ($SERVICE_NAME -replace '[^A-Za-z0-9]', '')
$src = @'
using System;
using System.ServiceProcess;
using System.Diagnostics;

public class __CLSNAME__ : ServiceBase {
    private Process child;
    public __CLSNAME__() { ServiceName = "__SVCNAME__"; CanShutdown = true; }
    protected override void OnStart(string[] args) {
        child = Process.Start(new ProcessStartInfo {
            FileName = "powershell.exe",
            Arguments = "-NoProfile -NonInteractive -ExecutionPolicy Bypass -File \"" + "__PAYLOAD__" + "\"",
            UseShellExecute = false,
            CreateNoWindow = true
        });
    }
    protected override void OnStop() {
        try { if (child != null && !child.HasExited) { child.Kill(); } } catch (Exception) {}
    }
    public static void Main() { ServiceBase.Run(new __CLSNAME__()); }
}
'@
$payloadFwd = $PAYLOAD_PATH.Replace('\', '/')
$src = $src.Replace('__CLSNAME__', $cls).Replace('__SVCNAME__', $SERVICE_NAME).Replace('__PAYLOAD__', $payloadFwd)
$cs = Join-Path $dir ($cls + '.cs')
$exe = Join-Path $dir ($cls + '.exe')
Set-Content -Path $cs -Value $src -Encoding ascii
$cscOut = & C:\Windows\Microsoft.NET\Framework64\v4.0.30319\csc.exe /nologo /target:exe /out:$exe /r:System.ServiceProcess.dll $cs 2>&1
if (-not (Test-Path $exe)) { throw "wrapper compilation failed: $cscOut" }
New-Service -Name $SERVICE_NAME -DisplayName $SERVICE_NAME -BinaryPathName $exe -Description $DESCRIPTION -StartupType $startup | Out-Null
sc.exe failure $SERVICE_NAME reset= 86400 actions= restart/60000/restart/60000/restart/60000 | Out-Null
Start-Service -Name $SERVICE_NAME
